const iconPaths = window.YuncangIcons;
const ico=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name]||iconPaths.file}</svg>`;
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.outerHTML=ico(el.dataset.icon)});}
hydrateIcons();
const routes={dashboard:{title:'工作台',icon:'home'},assistant:{title:'智能助手',icon:'sparkles'},purchase:{title:'采购订单',icon:'shopping'},inventory:{title:'库存管理',icon:'boxes'},canvas:{title:'方案画布',icon:'layout'},system:{title:'设计规范',icon:'palette'}};
const state={route:'dashboard',orderFilters:{id:'',supplier:'',status:''},orderPage:1,inventoryFilters:{product:'',warehouse:'',health:''},canvasMode:'business',zone:'main',density:'standard',example:'empty',question:'',stage:'welcome',planOpen:false,planTab:'plan',period:'未来 30 天',warehouse:'全部仓库',budget:'',lastFocus:null};
const orders=[{id:'PO20261016008',supplier:'上海汇川供应链',amount:48600,status:'待审核',date:'2026-10-16',owner:'陈晓',product:'工业控制器 YC-120',qty:120},{id:'PO20261016007',supplier:'杭州智联电子',amount:12800,status:'待入库',date:'2026-10-16',owner:'王明',product:'温湿度传感器 T-08',qty:200},{id:'PO20261015012',supplier:'苏州恒鑫精密',amount:36250,status:'部分入库',date:'2026-10-15',owner:'李楠',product:'精密连接器 C-32',qty:500},{id:'PO20261015011',supplier:'深圳瑞科科技',amount:67400,status:'已入库',date:'2026-10-15',owner:'陈晓',product:'边缘计算网关 G-01',qty:80},{id:'PO20261015010',supplier:'上海汇川供应链',amount:9600,status:'待审核',date:'2026-10-15',owner:'王明',product:'工业电源 P-24',qty:60},{id:'PO20261014006',supplier:'宁波优创工业',amount:21400,status:'已入库',date:'2026-10-14',owner:'李楠',product:'防水接线盒 B-10',qty:300},{id:'PO20261014005',supplier:'杭州智联电子',amount:18400,status:'待入库',date:'2026-10-14',owner:'陈晓',product:'温湿度传感器 T-08',qty:240},{id:'PO20261013009',supplier:'苏州恒鑫精密',amount:25800,status:'已入库',date:'2026-10-13',owner:'王明',product:'精密连接器 C-32',qty:400},{id:'PO20261013008',supplier:'深圳瑞科科技',amount:42000,status:'部分入库',date:'2026-10-13',owner:'李楠',product:'边缘计算网关 G-01',qty:50},{id:'PO20261012004',supplier:'宁波优创工业',amount:7600,status:'已入库',date:'2026-10-12',owner:'陈晓',product:'防水接线盒 B-10',qty:100},{id:'PO20261012003',supplier:'上海汇川供应链',amount:15900,status:'待审核',date:'2026-10-12',owner:'王明',product:'工业电源 P-24',qty:90},{id:'PO20261011002',supplier:'杭州智联电子',amount:8600,status:'已入库',date:'2026-10-11',owner:'李楠',product:'温湿度传感器 T-08',qty:120}];
const stocks=[{name:'工业控制器 YC-120',code:'SKU-001208',warehouse:'华东中心仓',stock:18,safe:50,health:'库存偏低',unit:'件'},{name:'温湿度传感器 T-08',code:'SKU-002104',warehouse:'华东中心仓',stock:32,safe:80,health:'库存偏低',unit:'个'},{name:'精密连接器 C-32',code:'SKU-003016',warehouse:'华南分仓',stock:46,safe:100,health:'库存偏低',unit:'件'},{name:'边缘计算网关 G-01',code:'SKU-004032',warehouse:'华东中心仓',stock:156,safe:60,health:'库存正常',unit:'台'},{name:'工业电源 P-24',code:'SKU-005014',warehouse:'华南分仓',stock:240,safe:100,health:'库存正常',unit:'台'},{name:'防水接线盒 B-10',code:'SKU-006081',warehouse:'华北分仓',stock:0,safe:200,health:'零库存',unit:'个'}];
const main=document.getElementById('main');
const money=value=>'¥ '+value.toLocaleString('zh-CN',{minimumFractionDigits:2});
const tag=(text)=>`<span class="tag ${text==='待审核'||text==='库存偏低'?'amber':text==='已入库'||text==='库存正常'?'green':text==='零库存'?'red':'blue'}">${text}</span>`;
function heading(title,subtitle,actions='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<p class="eyebrow">${eyebrow}</p>`:''}<h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3300);}
function closeMobile(){const sidebar=document.getElementById('sidebar');const wasOpen=sidebar.classList.contains('open');sidebar.classList.remove('open');document.querySelector('.workspace').inert=false;document.getElementById('mobile-menu').setAttribute('aria-expanded','false');if(wasOpen)document.getElementById('mobile-menu').focus();}
function openMobile(){const sidebar=document.getElementById('sidebar');sidebar.classList.add('open');document.querySelector('.workspace').inert=true;document.getElementById('mobile-menu').setAttribute('aria-expanded','true');sidebar.querySelector('a,button').focus();}
function go(route){if(!routes[route])route='dashboard';state.route=route;location.hash=route;render();closeMobile();}
function render(){clearPlanDrawer(false);main.className=state.route==='assistant'?'assistant-main':'';document.getElementById('page-title').textContent=routes[state.route].title;document.querySelectorAll('[data-route]').forEach(el=>{el.classList.toggle('active',el.dataset.route===state.route);el.setAttribute('aria-current',el.dataset.route===state.route?'page':'false');});document.getElementById('conversation-nav').hidden=state.route!=='assistant';const views={dashboard:renderDashboard,purchase:renderPurchase,inventory:renderInventory,assistant:renderAssistant,canvas:renderCanvas,system:renderSystem};views[state.route]();main.scrollTop=0;}
function renderDashboard(){main.innerHTML=heading('上午好，林经理','从今天最值得关注的事情开始。',`<button class="button" data-action="notifications">${ico('calendar')}今日待办</button>`,'2026 年 10 月 16 日 · 星期五 · 演示日期')+`<div class="ai-entry">${ico('sparkles')}<div class="ai-entry-body"><strong>把业务问题交给智能助手</strong><p>从库存风险到采购分析，先明确问题，再生成可审阅的分析计划。</p></div><button class="button" data-action="ask-ai">开始分析 ${ico('arrow')}</button></div><p class="table-meta" style="margin-bottom:10px">指标与待办为独立演示样例，不与本地订单列表逐项汇总。</p><div class="metrics"><div class="metric"><div class="metric-label">${ico('shopping')}待审核采购</div><div class="metric-value">08<span>笔</span></div><p class="metric-note">较昨日 <b>减少 2 笔</b></p></div><div class="metric"><div class="metric-label">${ico('boxes')}待入库采购</div><div class="metric-value">12<span>笔</span></div><p class="metric-note">其中 3 笔预计今日到货</p></div><div class="metric"><div class="metric-label">${ico('warning')}库存预警</div><div class="metric-value">06<span>项</span></div><p class="metric-note warn">3 项低于安全库存</p></div><div class="metric"><div class="metric-label">${ico('chart')}本月销售额</div><div class="metric-value">28.6<span>万元</span></div><p class="metric-note">较上月同期 <b>↓ 8.2%</b></p></div></div><div class="dashboard-grid"><section><div class="section-title"><h2>今日优先处理 <span class="count">3</span></h2><button class="text-button" data-route="purchase">查看全部 ${ico('right')}</button></div><div class="panel"><button class="task-row" data-order="PO20261016008"><span class="task-symbol amber">${ico('file')}</span><span class="task-copy"><strong>上海汇川供应链 · 采购订单待审核</strong><small>PO20261016008 · 陈晓 · ¥ 48,600.00</small></span><span class="tag amber">待审核</span>${ico('right')}</button><button class="task-row" data-order="PO20261016007"><span class="task-symbol">${ico('boxes')}</span><span class="task-copy"><strong>杭州智联电子 · 到货待入库</strong><small>PO20261016007 · 预计今日 14:00 到货</small></span>${ico('right')}</button><button class="task-row" data-action="stock-plan"><span class="task-symbol">${ico('chart')}</span><span class="task-copy"><strong>3 项产品低于安全库存</strong><small>建议先核对在途采购，再制定补货分析计划</small></span>${ico('right')}</button></div></section><section><div class="section-title"><h2>库存风险</h2><button class="text-button" data-route="inventory">查看库存 ${ico('right')}</button></div><div class="panel"><table class="mini-table"><thead><tr><th>产品名称</th><th>可用 / 安全</th><th>状态</th></tr></thead><tbody>${stocks.slice(0,3).map(s=>`<tr><td><span class="product-dot"></span>${s.name}</td><td class="number">${s.stock}<span class="muted"> / ${s.safe}</span></td><td>${tag('库存偏低')}</td></tr>`).join('')}</tbody></table><div class="panel-foot"><span>华东中心仓 · 华南分仓</span><button class="text-button" data-action="stock-plan">制定分析计划 ${ico('arrow')}</button></div></div></section></div><section class="activity-section"><div class="section-title"><h2>最近动态</h2><span class="muted" style="font-size:12px">演示记录</span></div><div class="activity">${ico('check')}采购订单 PO20261015011 已入库<span class="tag gray">华东中心仓</span><time>今天 09:32</time></div></section>`;}
function orderOptions(current){return `<option value="">全部状态</option>${['待审核','待入库','部分入库','已入库'].map(s=>`<option${current===s?' selected':''}>${s}</option>`).join('')}`;}
function renderPurchase(){main.innerHTML=heading('采购订单','清晰跟进每一笔采购，从申请到入库。',`<button class="button" data-action="purchase-help">${ico('info')}演示说明</button>`)+`<form class="filter-bar" id="order-filter"><label class="field"><span>采购订单号</span><input name="id" placeholder="输入订单号" aria-label="采购订单号"></label><label class="field"><span>供应商名称</span><input name="supplier" placeholder="输入供应商名称" aria-label="供应商名称"></label><label class="field"><span>订单状态</span><select name="status" aria-label="订单状态">${orderOptions(state.orderFilters.status)}</select></label><button type="submit" class="button primary">${ico('search')}查询</button><button type="button" class="button" data-action="reset-orders">重置</button></form><div class="table-panel purchase-table"><div class="table-title"><h2>采购订单列表 <span class="count" id="order-count"></span></h2><span>独立字段筛选 · 条件以 AND 组合</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>采购订单号</th><th>供应商</th><th>订单金额</th><th>状态</th><th>创建日期</th><th>经办人</th><th>操作</th></tr></thead><tbody id="order-rows"></tbody></table></div><div class="pagination" id="order-pagination"></div></div><p class="table-meta">点击订单号查看摘要、明细与流转轨迹。窄屏固定单号，中部可横向滚动。原型不提供真实审核、入库或提交操作。</p>`;const form=document.getElementById('order-filter');form.elements.id.value=state.orderFilters.id;form.elements.supplier.value=state.orderFilters.supplier;form.addEventListener('submit',e=>{e.preventDefault();state.orderFilters=Object.fromEntries(new FormData(form));state.orderPage=1;renderOrderRows();});renderOrderRows();}
function renderOrderRows(){const f=state.orderFilters;const rows=orders.filter(o=>o.id.toLowerCase().includes(f.id.trim().toLowerCase())&&o.supplier.includes(f.supplier.trim())&&(!f.status||o.status===f.status));const pages=Math.max(1,Math.ceil(rows.length/6));state.orderPage=Math.min(state.orderPage,pages);document.getElementById('order-count').textContent=rows.length;document.getElementById('order-rows').innerHTML=rows.slice((state.orderPage-1)*6,state.orderPage*6).map(o=>`<tr><td><button class="table-link number" data-order="${o.id}">${o.id}</button></td><td>${o.supplier}</td><td class="number">${money(o.amount)}</td><td>${tag(o.status)}</td><td class="number muted">${o.date}</td><td>${o.owner}</td><td><button class="text-button" data-order="${o.id}">查看详情</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-row">没有符合条件的演示订单，请调整筛选条件。</td></tr>';document.getElementById('order-pagination').innerHTML=`<span>共 ${rows.length} 条 · 每页 6 条 · 演示数据</span><div class="pages"><button data-page="${state.orderPage-1}" aria-label="上一页" ${state.orderPage===1?'disabled':''}>${ico('left')}</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${state.orderPage===i+1?'active':''}" aria-label="第 ${i+1} 页">${i+1}</button>`).join('')}<button data-page="${state.orderPage+1}" aria-label="下一页" ${state.orderPage===pages?'disabled':''}>${ico('right')}</button></div>`;}
function openOrder(id){const o=orders.find(x=>x.id===id);if(!o)return;const dialog=document.getElementById('detail-dialog');document.getElementById('detail-content').innerHTML=`<div class="dialog-heading"><div><p class="eyebrow">采购订单 · 演示详情</p><h2>${o.id}</h2><p>只读预览 · 不连接真实单据</p></div><button class="icon-button" data-close="detail-dialog" aria-label="关闭订单详情">${ico('close')}</button></div>${tag(o.status)}<dl class="detail-fields"><div><dt>供应商</dt><dd>${o.supplier}</dd></div><div><dt>订单金额</dt><dd class="number">${money(o.amount)}</dd></div><div><dt>经办人</dt><dd>${o.owner}</dd></div><div><dt>创建日期</dt><dd>${o.date}</dd></div><div><dt>收货仓库</dt><dd>华东中心仓</dd></div><div><dt>付款方式</dt><dd>月结 30 天</dd></div></dl><h3 class="detail-subtitle">商品明细</h3><div class="table-panel"><table class="data-table"><thead><tr><th>产品</th><th>数量</th><th>单位</th></tr></thead><tbody><tr><td>${o.product}</td><td>${o.qty}</td><td>件</td></tr></tbody></table></div><h3 class="detail-subtitle">流转轨迹 · 演示</h3><ol class="timeline"><li>采购申请已创建<small>${o.date} 09:12 · ${o.owner}</small></li><li>采购资料已补充<small>${o.date} 09:28 · ${o.owner}</small></li><li>当前状态：${o.status}<small>此轨迹仅演示信息结构</small></li></ol><div class="notice">${ico('info')}单据上下文在正式版本中需经权限校验后读取。这里仅将演示订单号填入助手，不自动查询。</div><div class="detail-actions"><button class="button primary" data-order-ai="${o.id}">${ico('sparkles')}请 AI 解读</button><button class="button" data-close="detail-dialog">关闭详情</button></div>`;dialog.showModal();}
function renderInventory(){const f=state.inventoryFilters;main.innerHTML=heading('库存管理','先看到风险，再决定下一步。',`<button class="button" data-action="stock-plan">${ico('sparkles')}制定分析计划</button>`)+`<form class="filter-bar" id="stock-filter"><label class="field"><span>产品名称</span><input name="product" placeholder="输入产品名称"></label><label class="field"><span>仓库</span><select name="warehouse"><option value="">全部仓库</option>${['华东中心仓','华南分仓','华北分仓'].map(w=>`<option${f.warehouse===w?' selected':''}>${w}</option>`).join('')}</select></label><label class="field"><span>库存健康</span><select name="health"><option value="">全部状态</option>${['库存偏低','库存正常','零库存'].map(w=>`<option${f.health===w?' selected':''}>${w}</option>`).join('')}</select></label><button class="button primary" type="submit">${ico('search')}查询</button><button class="button" type="button" data-action="reset-stock">重置</button></form><div class="table-panel"><div class="table-title"><h2>库存明细 <span class="count" id="stock-count"></span></h2><span>可用库存口径 · 演示数据</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>产品名称 / 编码</th><th>仓库</th><th>可用库存</th><th>安全库存</th><th>库存健康</th><th>操作</th></tr></thead><tbody id="stock-rows"></tbody></table></div></div><div class="notice">${ico('info')}库存健康标签、安全库存和风险摘要为原型演示规则。正式落地前需确认库存口径、库存阈值和仓库权限。</div>`;const form=document.getElementById('stock-filter');form.elements.product.value=f.product;form.addEventListener('submit',e=>{e.preventDefault();state.inventoryFilters=Object.fromEntries(new FormData(form));renderStockRows();});renderStockRows();}
function renderStockRows(){const f=state.inventoryFilters;const rows=stocks.filter(s=>s.name.includes(f.product.trim())&&(!f.warehouse||s.warehouse===f.warehouse)&&(!f.health||s.health===f.health));document.getElementById('stock-count').textContent=rows.length;document.getElementById('stock-rows').innerHTML=rows.map((s,i)=>`<tr><td>${s.name}<small style="display:block;color:#626873;font-size:12px">${s.code}</small></td><td>${s.warehouse}</td><td class="number">${s.stock}<span class="muted" style="margin-left:5px;font-size:12px">${s.unit}</span></td><td class="number muted">${s.safe}</td><td>${tag(s.health)}</td><td><button class="text-button" data-stock-ai="${stocks.indexOf(s)}">制定分析计划</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty-row">没有符合条件的演示库存。</td></tr>';}
function askAI(question=''){state.question='';state.stage='welcome';state.planOpen=false;state.planTab='plan';state.period='未来 30 天';state.warehouse='全部仓库';state.budget='';go('assistant');const input=document.getElementById('ai-input');input.value=question;input.focus();}
function renderAssistant(){main.innerHTML=`<section class="assistant-work"><div class="assistant-toolbar"><strong>${ico('sparkles')} 业务分析助手 <span class="tag gray" style="margin-left:5px">仅生成计划</span></strong><div style="display:flex;gap:7px"><button class="button" data-action="new-chat">${ico('plus')}新建会话</button><button class="button" data-action="toggle-plan">${ico('panel')}计划画布</button></div></div><div class="assistant-scroll" id="assistant-scroll"></div><div class="composer-wrap"><form class="composer" id="ai-form"><textarea id="ai-input" rows="2" aria-label="输入业务问题" placeholder="描述你想分析的业务问题…"></textarea><div class="composer-bottom"><span class="composer-note">${ico('sparkles')}先澄清，再生成可审阅计划</span><button class="send-button" type="submit" aria-label="发送问题">${ico('up')}</button></div></form><p class="composer-foot">交互流程演示 · 不调用模型、不执行 SQL 或 Python、不创建采购单</p></div></section><aside class="plan-panel" id="plan-panel" ${state.planOpen?'':'hidden'} aria-label="分析计划画布"><div class="plan-header"><h2>分析计划画布</h2><button class="icon-button" data-action="toggle-plan" aria-label="收起计划画布">${ico('close')}</button></div><div class="plan-tabs"><button data-plan-tab="plan" class="${state.planTab==='plan'?'active':''}">计划</button><button data-plan-tab="basis" class="${state.planTab==='basis'?'active':''}">依据与边界</button></div><div class="plan-body" id="plan-body"></div><div class="plan-footer"><button class="button" data-action="export-plan" ${state.stage==='plan'?'':'disabled'}>${ico('download')}导出计划 · Markdown</button></div></aside><div class="drawer-shade" data-action="toggle-plan"></div>`;renderChat();renderPlan();document.getElementById('ai-form').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('ai-input');if(!input.value.trim()){toast('请先描述一个业务问题');input.focus();return;}state.question=input.value.trim();state.stage='clarify';state.planOpen=false;state.planTab='plan';input.value='';renderChat();renderPlan();document.getElementById('plan-panel').hidden=true;});}
function renderChat(){const root=document.getElementById('assistant-scroll');if(state.stage==='welcome'){root.innerHTML=`<div class="assistant-welcome"><div class="assistant-mark">${ico('sparkles')}</div><h1>让每个业务问题，<br>都有清晰的下一步。</h1><p>我会帮助你拆解问题、明确分析范围，<br>生成一份可以逐步审阅的分析计划。</p><div class="suggestions"><button class="suggestion" data-suggestion="分析未来 30 天的库存风险，帮我制定补货分析计划">${ico('boxes')}未来 30 天，哪些产品需要重点关注？${ico('arrow')}</button><button class="suggestion" data-suggestion="对比本月和上月的采购金额，制定波动原因分析计划">${ico('chart')}本月采购金额变化，应该从哪里看起？${ico('arrow')}</button><button class="suggestion" data-suggestion="制定供应商交付表现分析计划，关注延期与到货完整率">${ico('shopping')}如何评估主要供应商的交付表现？${ico('arrow')}</button></div><p class="suggestions-caption">以上是固定问题模板 · 点击仅填入输入框</p></div>`;return;}root.innerHTML=`<div class="chat-message chat-user"><div class="user-bubble" id="user-question"></div></div><div class="chat-message chat-ai"><div class="chat-ai-head">${ico('sparkles')}云仓助手 <span class="tag gray">交互演示</span></div><p>${state.stage==='clarify'?'开始之前，先确认这次分析的范围。以下选项会写入计划，确保你能看懂每一步准备做什么。':'分析计划已准备好。你可以在右侧画布审阅范围、步骤与执行边界。'}</p>${state.stage==='clarify'?`<form class="clarification" id="clarify-form"><h3>明确分析范围</h3><span class="clarify-label">时间范围</span><div class="choice-row">${['未来 7 天','未来 30 天','未来 90 天'].map((p,i)=>`<label><input type="radio" name="period" value="${p}" ${state.period===p?'checked':''}>${p}</label>`).join('')}</div><label class="field"><span>仓库范围</span><select name="warehouse">${['全部仓库','华东中心仓','华南分仓','华北分仓'].map(w=>`<option${state.warehouse===w?' selected':''}>${w}</option>`).join('')}</select></label><label class="field"><span>预算上限（可选，元）</span><input name="budget" type="number" min="0" step="100" placeholder="留空表示本次不限制预算"></label><button type="submit" class="button primary">生成分析计划 ${ico('arrow')}</button></form>`:`<p class="plan-result">当前状态：计划草稿。尚未读取真实单据，也未执行任何查询或分析。</p><div class="result-actions"><button class="button" data-action="open-plan">${ico('panel')}查看计划</button><button class="button" data-action="edit-scope">调整范围</button></div>`}</div>`;document.getElementById('user-question').textContent=state.question;if(state.stage==='clarify'){const form=document.getElementById('clarify-form');form.elements.budget.value=state.budget;form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);state.period=d.get('period');state.warehouse=d.get('warehouse');state.budget=d.get('budget');state.stage='plan';state.planOpen=true;state.planTab='plan';renderChat();renderPlan();document.getElementById('plan-panel').hidden=false;});}root.scrollTop=root.scrollHeight;}
function renderPlan(){const body=document.getElementById('plan-body');if(!body)return;document.querySelectorAll('[data-plan-tab]').forEach(b=>b.classList.toggle('active',b.dataset.planTab===state.planTab));const exportBtn=document.querySelector('[data-action="export-plan"]');exportBtn.disabled=state.stage!=='plan';if(state.planTab==='basis'){body.innerHTML=`<p class="eyebrow">可落地的边界</p><h3>先连接证据，再执行分析</h3><p class="plan-summary">本原型展示交互和信息组织方式，不代表后端已经具备下列能力。</p><ul class="boundary-list"><li><strong>问题模板</strong>首页的建议问题是固定文案，点击只填入输入框。</li><li><strong>计划生成</strong>当前演示使用本地固定步骤，无模型调用。正式版应复用现有 AI 计划接口及其实际字段。</li><li><strong>SQL_QUERY / PYTHON_ANALYSIS</strong>仅代表准备执行的步骤。现有 AI 只生成计划，本原型不执行 SQL 或 Python。</li><li><strong>单据与仓库权限</strong>正式版需要后端校验组织、仓库和单据访问范围；不能依赖前端隐藏控件。</li><li><strong>采购动作</strong>不自动采购、不自动审核、不自动创建单据。业务写入需独立接口和明确确认。</li><li><strong>导出</strong>仅将当前计划导出为本地 Markdown 文件，不上传业务数据。</li></ul>`;return;}if(state.stage!=='plan'){body.innerHTML=`<div class="plan-empty"><div>${ico('layout')}<h3>计划将在这里展开</h3><p>提出问题并确认分析范围后，<br>你可以在此逐步审阅分析计划。</p></div></div>`;return;}body.innerHTML=`<div class="plan-status"><span class="status-dot"></span>草稿已生成 · 尚未执行</div><h3>业务分析计划</h3><p class="plan-summary" id="plan-question"></p><div class="notice" style="margin-top:15px;font-size:12px">${ico('info')}<span id="scope-summary"></span></div><div class="plan-step"><span class="step-number">1</span><strong>提取业务数据</strong><p>先核对字段、口径和权限，再按已确认的范围准备只读查询。此步骤仅规划，不查询真实数据库。</p><code>SQL_QUERY · 计划</code></div><div class="plan-step"><span class="step-number">2</span><strong>分析差异与风险</strong><p>准备识别库存缺口、交付变化或采购波动，并规划输出依据与建议。指标需与业务口径对齐，决策由业务人员独立确认。</p><code>PYTHON_ANALYSIS · 计划</code></div>`;document.getElementById('plan-question').textContent=state.question;document.getElementById('scope-summary').textContent=`${state.period} · ${state.warehouse} · ${state.budget?'预算上限 ¥ '+Number(state.budget).toLocaleString():'不限制预算'}`;}
function exportPlan(){if(state.stage!=='plan')return;const text=`# 云仓 ERP · 业务分析计划\n\n> 交互原型 · 演示数据 · 计划尚未执行\n\n## 业务问题\n${state.question}\n\n## 分析范围\n- 时间：${state.period}\n- 仓库：${state.warehouse}\n- 预算：${state.budget?state.budget+' 元':'不限制'}\n\n## 计划步骤\n1. SQL_QUERY：确认字段、口径和权限，规划只读业务查询；未执行。\n2. PYTHON_ANALYSIS：规划差异与风险分析及其依据、明细和建议；未执行。\n\n## 执行边界\n本原型不调用模型、不执行 SQL 或 Python、不读取真实单据、不自动采购或审核。\n`;const blob=new Blob([text],{type:'text/markdown;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='云仓ERP-分析计划-演示.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('分析计划已导出为 Markdown');}
const zoneDetails={sidebar:{title:'导航区 · 固定 232 px',text:'稳定承载业务导航、工作空间和近期会话。AI 页面保留同一导航，避免从业务系统进入另一个独立应用。',items:['品牌区与导航起点保持稳定','业务分组：工作空间 / 业务管理 / 设计提案','当前项使用浅蓝底与深蓝文字，不用大面积高饱和色']},header:{title:'顶栏 · 固定 56 px',text:'只承担当前位置、全局状态与轻量操作。页面标题和主要业务动作放在内容区，减少重复信息。',items:['面包屑表达当前位置','全局通知为待办入口，不编造未读数量','保留角色入口，避免顶栏堆叠业务工具']},main:{title:'内容区 · 自适应宽度',text:'业务页面以筛选、列表和详情为核心；AI 页面以问题、澄清和计划为核心。在同一空间中适配任务密度。',items:['业务模式：28–40 px 外边距，表格行高 52 / 44 px','AI 模式：对话正文最大宽度约 700 px','正文 14 px；AI 15 px / 1.8 行高；页面标题 24 px']},right:{title:'结果画布 · 建议 382 px',text:'将可审阅的计划与对话分开呈现。1440 px 桌面下并排；小于 1280 px 改为覆盖抽屉，保障主区可读。',items:['画布最小宽度 360 px，支持收起','计划 / 依据与边界两类信息切换','不展示虚构的查询结果，不将计划表现成已执行']}};
function renderCanvas(){main.innerHTML=heading('让业务与 AI，共用一个工作空间','点击画布中的区域，查看布局职责与尺寸。',`<div class="mode-toggle"><button data-canvas-mode="business" class="${state.canvasMode==='business'?'active':''}">业务模式</button><button data-canvas-mode="ai" class="${state.canvasMode==='ai'?'active':''}">AI 模式</button></div>`,'LAYOUT PROPOSAL · 01')+`<div class="canvas-board"><div class="canvas-size"><span>桌面布局示意 · 非真实业务页面</span><span>建议视口 1440 × 900 px</span></div><div class="layout-preview"><button class="layout-zone preview-sidebar ${state.zone==='sidebar'?'selected':''}" data-zone="sidebar"><div class="preview-logo">云仓 ERP</div><span class="zone-label">01 / 主导航</span><span class="zone-size">232 px · 固定</span><div class="preview-nav-line active"></div><div class="preview-nav-line"></div><div class="preview-nav-line"></div><div class="preview-nav-line"></div></button><div class="preview-work"><button class="layout-zone preview-header ${state.zone==='header'?'selected':''}" data-zone="header"><span class="zone-label">02 / 顶栏 · 56 px</span></button><div class="preview-main-wrap"><button class="layout-zone preview-main ${state.zone==='main'?'selected':''}" data-zone="main"><span class="zone-label">03 / ${state.canvasMode==='ai'?'对话与澄清':'业务工作区'}</span><span class="zone-size">自适应 · ${state.canvasMode==='ai'?'正文 ≤ 700 px':'内容留白 28–40 px'}</span><div class="preview-title-line"></div><div class="preview-text-line"></div><div class="preview-metrics"><span></span><span></span><span></span></div><div class="preview-table"><span></span><span></span><span></span></div></button><button class="layout-zone preview-right ${state.zone==='right'?'selected':''}" data-zone="right" ${state.canvasMode==='ai'?'':'hidden'}><span class="zone-label">04 / 计划画布</span><span class="zone-size">382 px</span><div class="preview-text-line"></div><div class="preview-text-line"></div><div class="preview-text-line"></div></button></div></div></div></div><div class="canvas-info"><section class="spec-info" id="zone-info"></section><section class="spec-info"><h2>从现有页面到新布局</h2><p>保留云仓品牌、HarmonyOS Sans 与业务主色。重点改变空间组织、层级、信息密度，以及 AI 与业务页面的关系。</p><ul><li>桌面：稳定侧栏 + 简洁顶栏 + 任务主区</li><li>窄屏：折叠导航，表格保留局部横向滚动</li><li>移动端：抽屉导航，计划画布独立展开</li></ul><div class="evidence-links"><a href="evidence/01-dashboard.png" target="_blank" rel="noopener">${ico('external')}当前工作台截图</a><a href="evidence/05-ai.png" target="_blank" rel="noopener">${ico('external')}当前 AI 页面截图</a></div></section></div>`;renderZone();}
function renderZone(){const d=zoneDetails[state.zone];document.getElementById('zone-info').innerHTML=`<p class="eyebrow">选中区域 · 布局说明</p><h2>${d.title}</h2><p>${d.text}</p><ul>${d.items.map(x=>`<li>${x}</li>`).join('')}</ul>`;}
function renderSystem(){main.innerHTML=heading('设计规范','一套安静、清晰、适合长时间工作的界面语言。','','DESIGN FOUNDATION · 01')+`<div class="system-grid"><section class="spec-card"><h2>字体与层级</h2><p class="spec-description">沿用现有 HarmonyOS Sans 字体，本原型未做资源压缩。</p><div class="type-row"><span style="font-size:24px;font-weight:600">页面标题</span><small>24 px / 600</small></div><div class="type-row"><span style="font-size:16px;font-weight:600">区块标题，承接主要信息</span><small>16 px / 600</small></div><div class="type-row"><span style="font-size:14px">业务正文、表格与表单内容</span><small>14 px / 400</small></div><div class="type-row"><span style="font-size:15px;line-height:1.8">AI 对话内容，给阅读更多空间。</span><small>15 px / 1.8</small></div><div class="type-row"><span style="font-size:12px;color:#626873">辅助信息、说明与更新时间</span><small>12 px / 400</small></div></section><section class="spec-card"><h2>配色与语义</h2><p class="spec-description">中性底色承载信息，蓝色强调动作，状态色只用于状态。</p><div class="swatches">${[['品牌蓝','#315DCE'],['正文','#20242C'],['次要文字','#626873'],['工作区','#F7F8FA'],['边框','#E3E6EB'],['导航背景','#F3F3F1']].map(([name,color])=>`<div class="swatch"><div class="swatch-color" style="background:${color}"></div><strong>${name}</strong><small>${color}</small></div>`).join('')}</div><div style="display:flex;gap:9px;margin-top:25px">${tag('待审核')}${tag('已入库')}${tag('库存偏低')}${tag('零库存')}</div></section><section class="spec-card"><h2>内容密度</h2><p class="spec-description">切换会真实改变本原型全部业务表格的行高。</p><div class="density-choices"><button data-density="standard" class="density-choice ${state.density==='standard'?'active':''}">标准模式<small>52 px 行高 · 日常办公</small></button><button data-density="compact" class="density-choice ${state.density==='compact'?'active':''}">紧凑模式<small>44 px 行高 · 批量浏览</small></button></div><div class="table-panel density-demo"><table class="data-table"><thead><tr><th>采购订单</th><th>状态</th><th>金额</th></tr></thead><tbody><tr><td>PO20261016008</td><td>${tag('待审核')}</td><td>¥ 48,600</td></tr><tr><td>PO20261016007</td><td>${tag('待入库')}</td><td>¥ 12,800</td></tr><tr><td>PO20261015012</td><td>${tag('部分入库')}</td><td>¥ 36,250</td></tr></tbody></table></div></section><section class="spec-card"><h2>状态与反馈</h2><p class="spec-description">空态告诉用户下一步，加载态保持结构，错误态提供恢复入口。</p><div class="state-tabs">${[['empty','空状态'],['loading','加载中'],['error','错误反馈']].map(([key,label])=>`<button data-example="${key}" class="${state.example===key?'active':''}">${label}</button>`).join('')}</div><div class="state-example" id="state-example"></div></section></div><div class="notice">${ico('info')}生产落地时应统一为组件库 token。此页的密度与状态切换仅作用于本演示；不会改变现有 ERP 设置。</div>`;renderStateExample();}
function renderStateExample(){const el=document.getElementById('state-example');if(state.example==='empty')el.innerHTML=`${ico('inbox')}<strong>暂时没有采购订单</strong><p>可以调整筛选条件，或查看其他时间范围。</p><button class="button" data-route="purchase">查看演示订单</button>`;else if(state.example==='loading')el.innerHTML=`<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><p>正在加载演示内容…<br>此处用于展示加载样式，不发起请求。</p>`;else el.innerHTML=`${ico('warning')}<strong>订单列表加载失败</strong><p>请检查网络后重试。当前展示为模拟错误状态。</p><button class="button" data-action="retry-state">${ico('refresh')}重试演示</button>`;}
function info(title,content){document.getElementById('info-content').innerHTML=`<div class="dialog-heading"><h2>${title}</h2><button class="icon-button" data-close="info-dialog" aria-label="关闭说明">${ico('close')}</button></div>${content}<button class="button" data-close="info-dialog">知道了</button>`;document.getElementById('info-dialog').showModal();}
function notifications(){info('今日待办 · 演示',`<p>8 笔采购订单待审核<br>3 笔采购预计今日到货<br>3 项产品低于安全库存</p><div class="notice">${ico('info')}这些是固定演示数据，不展示虚构的未读通知或实时消息。</div>`);}
function renderCommands(value=''){const entries=Object.entries(routes).filter(([key,v])=>v.title.includes(value.trim()));document.getElementById('command-results').innerHTML=entries.map(([key,v])=>`<button class="command-result" data-command="${key}">${ico(v.icon)}${v.title}${ico('arrow')}</button>`).join('')||'<p class="dialog-caption" style="padding-bottom:20px">没有匹配的页面。此处仅提供导航查找。</p>';}
function openCommands(){renderCommands();const input=document.getElementById('command-input');input.value='';document.getElementById('command-dialog').showModal();input.focus();}
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){go(route.dataset.route);return;}const close=e.target.closest('[data-close]');if(close){document.getElementById(close.dataset.close).close();return;}const command=e.target.closest('[data-command]');if(command){document.getElementById('command-dialog').close();go(command.dataset.command);return;}const order=e.target.closest('[data-order]');if(order){openOrder(order.dataset.order);return;}const page=e.target.closest('[data-page]');if(page){state.orderPage=Number(page.dataset.page);renderOrderRows();return;}const orderAI=e.target.closest('[data-order-ai]');if(orderAI){document.getElementById('detail-dialog').close();askAI(`请为演示订单 ${orderAI.dataset.orderAi} 制定解读计划。此处是原型单据上下文，尚未读取真实订单。`);return;}const stockAI=e.target.closest('[data-stock-ai]');if(stockAI){const s=stocks[Number(stockAI.dataset.stockAi)];askAI(`为 ${s.warehouse} 的 ${s.name} 制定库存分析计划。当前可用库存 ${s.stock}，安全库存 ${s.safe}（均为演示数据）。`);return;}const suggestion=e.target.closest('[data-suggestion]');if(suggestion){const input=document.getElementById('ai-input');input.value=suggestion.dataset.suggestion;input.focus();return;}const tab=e.target.closest('[data-plan-tab]');if(tab){state.planTab=tab.dataset.planTab;renderPlan();return;}const mode=e.target.closest('[data-canvas-mode]');if(mode){state.canvasMode=mode.dataset.canvasMode;renderCanvas();return;}const zone=e.target.closest('[data-zone]');if(zone){state.zone=zone.dataset.zone;document.querySelectorAll('[data-zone]').forEach(el=>el.classList.toggle('selected',el===zone));renderZone();return;}const density=e.target.closest('[data-density]');if(density){state.density=density.dataset.density;document.body.classList.toggle('compact',state.density==='compact');renderSystem();return;}const example=e.target.closest('[data-example]');if(example){state.example=example.dataset.example;document.querySelectorAll('[data-example]').forEach(el=>el.classList.toggle('active',el===example));renderStateExample();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;const actions={'notifications':notifications,'ask-ai':()=>askAI(),'stock-plan':()=>askAI('分析未来 30 天的库存风险，结合安全库存与在途采购，制定可审阅的补货分析计划。'),'purchase-help':()=>info('采购交互演示','<p>可使用订单号、供应商名称、状态组合筛选，切换分页，点击订单查看详情，或将订单上下文填入智能助手。</p><p style="margin-top:12px">所有金额、单号与流转轨迹均为演示数据，不发生真实业务写入。</p>'),'reset-orders':()=>{state.orderFilters={id:'',supplier:'',status:''};state.orderPage=1;renderPurchase();},'reset-stock':()=>{state.inventoryFilters={product:'',warehouse:'',health:''};renderInventory();},'new-chat':()=>askAI(),'toggle-plan':()=>{state.planOpen=!state.planOpen;document.getElementById('plan-panel').hidden=!state.planOpen;},'open-plan':()=>{state.planOpen=true;document.getElementById('plan-panel').hidden=false;},'edit-scope':()=>{state.stage='clarify';state.planOpen=false;document.getElementById('plan-panel').hidden=true;renderChat();renderPlan();},'export-plan':exportPlan,'retry-state':()=>{state.example='loading';renderSystem();setTimeout(()=>{if(state.route==='system'){state.example='empty';renderSystem();toast('模拟重试完成，已恢复为空状态');}},1000);}};actions[action]?.();});
document.getElementById('mobile-menu').setAttribute('aria-controls','sidebar');
document.getElementById('mobile-menu').setAttribute('aria-expanded','false');
document.getElementById('mobile-menu').addEventListener('click',()=>document.getElementById('sidebar').classList.contains('open')?closeMobile():openMobile());
document.getElementById('sidebar-shade').addEventListener('click',closeMobile);
document.getElementById('command-open').addEventListener('click',openCommands);
document.getElementById('command-input').addEventListener('input',e=>renderCommands(e.target.value));
document.getElementById('command-input').addEventListener('keydown',e=>{if(e.key==='Enter'){document.querySelector('[data-command]')?.click();}});
document.getElementById('workspace-info').addEventListener('click',()=>info('当前工作空间','<p>云仓科技 · 演示工作空间</p><p style="margin-top:12px">正式版本可在这里切换已授权的组织。组织列表、权限与隔离需由后端提供；本原型不模拟切换真实组织。</p>'));
document.getElementById('settings-open').addEventListener('click',()=>info('系统设置','<p>此入口保留工作空间设置的位置。正式落地时可承载组织、成员、角色权限与基础配置。</p><p style="margin-top:12px">本原型的字号、配色、密度和状态演示可在「设计规范」页面查看。不会修改生产系统设置。</p>'));
document.getElementById('notifications-open').addEventListener('click',notifications);
document.getElementById('new-chat').addEventListener('click',()=>askAI());
document.getElementById('recent-chat').addEventListener('click',()=>{if(state.question){go('assistant');}else{askAI('分析未来 30 天的库存风险，帮我制定补货分析计划');toast('这是固定历史入口，仅填入演示问题');}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!document.querySelector('dialog[open]'))openCommands();}if(e.key==='Escape'){closeMobile();if(state.route==='assistant'&&state.planOpen){state.planOpen=false;document.getElementById('plan-panel').hidden=true;}}});
document.querySelectorAll('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{if(e.target===dialog){const box=dialog.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)dialog.close();}});});
/* 移动导航保持键盘焦点，背景内容用 inert 阻止误操作。 */
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!document.getElementById('sidebar').classList.contains('open')||document.querySelector('dialog[open]'))return;const controls=[...document.getElementById('sidebar').querySelectorAll('a,button')].filter(el=>el.offsetParent!==null&&!el.disabled);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
window.addEventListener('resize',()=>{if(window.innerWidth>760&&document.getElementById('sidebar').classList.contains('open'))closeMobile();});
/* 小于 1280 px 时画布是模态抽屉；桌面宽屏继续保留并排阅读。 */
let activePlanDrawer=null;
let planDrawerTrigger=null;
const drawerBackgrounds=()=>[document.getElementById('sidebar'),document.querySelector('.topbar'),document.querySelector('.assistant-work'),document.querySelector('.workspace-footer')].filter(Boolean);
function clearPlanDrawer(restoreFocus=true){const oldPanel=activePlanDrawer;if(!oldPanel)return;activePlanDrawer=null;drawerBackgrounds().forEach(el=>el.inert=false);oldPanel.removeAttribute('role');oldPanel.removeAttribute('aria-modal');if(restoreFocus){const trigger=planDrawerTrigger?.isConnected?planDrawerTrigger:document.querySelector('[data-action="toggle-plan"]');trigger?.focus();}planDrawerTrigger=null;}
function syncPlanDrawer(){const panel=document.getElementById('plan-panel');const shouldBeModal=state.route==='assistant'&&panel&&!panel.hidden&&window.innerWidth<1280;if(!shouldBeModal){clearPlanDrawer();return;}if(activePlanDrawer===panel)return;clearPlanDrawer(false);planDrawerTrigger=document.activeElement;activePlanDrawer=panel;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('tabindex','-1');drawerBackgrounds().forEach(el=>el.inert=true);(panel.querySelector('button:not(:disabled)')||panel).focus();}
new MutationObserver(syncPlanDrawer).observe(main,{subtree:true,childList:true,attributes:true,attributeFilter:['hidden']});
window.addEventListener('resize',syncPlanDrawer);
document.addEventListener('keydown',e=>{if(!activePlanDrawer||document.querySelector('dialog[open]'))return;if(e.key==='Tab'){const controls=[...activePlanDrawer.querySelectorAll('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]')].filter(el=>el.offsetParent!==null);const first=controls[0],last=controls.at(-1);if(!first){e.preventDefault();activePlanDrawer.focus();}else if(e.shiftKey&&(document.activeElement===first||document.activeElement===activePlanDrawer)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(routes[route]&&route!==state.route){state.route=route;render();}});
state.route=routes[location.hash.slice(1)]?location.hash.slice(1):'dashboard';render();
